// The nested collection is mutable, so the outer `val` guarantees nothing useful.
data class CartState(
    val lines: MutableList<CartLine>,
    val note: String,
)

@Composable
fun CartScreen() {
    var cart by remember { mutableStateOf(CartState(mutableListOf(), "")) }
    // ...
}

// Path 1 — mutate in place. No write to the holder at all.
cart.lines.add(line)

// Path 2 — mutate in place, then reassign a copy. A write happens.
cart.lines.add(line)
cart = cart.copy()

// Path 3 — produce a genuinely different value.
cart = cart.copy(lines = (cart.lines + line).toMutableList())

data class CartState(
    val lines: List<CartLine>,   // read-only type and, by construction, never shared mutably
    val note: String,
)

// Every update is now a replacement, and every replacement is a real change.
cart = cart.copy(lines = cart.lines + line)

